// The agent is asked for raw JSON, but LLMs still wrap it in ```json fences often
// enough that parsing defensively is cheaper than a retry loop.
const raw = String($input.first().json.output ?? '').trim();
const cleaned = raw.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();

let idea;
try {
  idea = JSON.parse(cleaned);
} catch (e) {
  // Last resort: pull the outermost {...} out of surrounding prose.
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (!match) {
    throw new Error('Design Director did not return JSON. Got: ' + raw.slice(0, 200));
  }
  idea = JSON.parse(match[0]);
}

for (const key of ['title', 'description', 'concept']) {
  if (!idea[key] || !String(idea[key]).trim()) {
    throw new Error(`Design Director output is missing "${key}"`);
  }
}

// Every trend fed to the model is consumed by this run, whether or not the
// resulting idea turns out to be a duplicate server-side.
const trends = $('Load New Trends').first().json.data || [];

return [{
  json: {
    title: String(idea.title).trim(),
    description: String(idea.description).trim(),
    concept: String(idea.concept).trim(),
    source_trend_ids: trends.map((t) => t.id).filter(Boolean),
  },
}];
